package com.curso.estoque2026.api.dto;
import io.swagger.v3.oas.annotations.media.Schema;
import com.curso.estoque2026.domain.Status;
import java.math.BigDecimal; import java.time.LocalDate;
@Schema(description = "Representação completa de uma bebida")
public record BebidaResponse( @Schema(description = "Identificador da bebida", example = "1") Long id, @Schema(description = "Código de barras único", example = "7891999000010") String codigoBarras, @Schema(description = "Descrição comercial", example = "Refrigerante Cola 2L") String descricao, @Schema(description = "Saldo atual", example = "24.000") BigDecimal saldoEstoque, @Schema(description = "Preço por unidade", example = "8.50") BigDecimal valorUnitario, @Schema(description = "Limite que indica reposição", example = "10.000") BigDecimal estoqueMinimo, @Schema(description = "Saldo multiplicado pelo valor unitário", example = "204.00") BigDecimal valorEstoque, @Schema(description = "Data de cadastro", example = "2026-10-29") LocalDate dataCadastro, @Schema(description = "Situação da bebida", example = "ATIVO") Status status, @Schema(description = "Identificador da categoria", example = "1") Long categoriaId, @Schema(description = "Nome da categoria", example = "Refrigerantes") String categoriaNome, @Schema(description = "Identificador do fornecedor, quando associado", example = "1") Long fornecedorId, @Schema(description = "Razão social do fornecedor, quando associado", example = "Distribuidora de Bebidas Central Ltda.") String fornecedorRazaoSocial ) { }

